#!/bin/bash
# Generated by MobileCode. Signs at export with your App Store Connect API key (cloud-managed signing).
set -euo pipefail
MODE="${1:-adhoc}"
KEY_DIR="$HOME/.appstoreconnect/private_keys"
KEY="$KEY_DIR/AuthKey_${ASC_KEY_ID}.p8"
mkdir -p "$KEY_DIR"
echo "$ASC_KEY_P8_B64" | base64 --decode > "$KEY"
# Diagnostics: structure only, never the key material.
echo "key file: $(wc -c < "$KEY" | tr -d ' ') bytes, $(wc -l < "$KEY" | tr -d ' ') newlines, $(tr -cd '\r' < "$KEY" | wc -c | tr -d ' ') CRs"
echo "key first line: $(head -1 "$KEY" | cut -c1-40)"
echo "key last line:  $(tail -1 "$KEY" | cut -c1-40)"
echo "key line lengths: $(awk '{print length($0)}' "$KEY" | sort -n | uniq -c | tr '\n' ';')"
if openssl pkey -in "$KEY" -noout 2>/dev/null; then echo "openssl: key parses"; else echo "openssl: key does NOT parse"; fi

# Projects are described by project.yml (XcodeGen) so the AI edits one small text file.
if [ -f project.yml ]; then
  # App name: keep what project.yml says; the starter default becomes the repo name.
  APP_NAME="$(echo "${GITHUB_REPOSITORY#*/}" | tr '_-' '  ' | awk '{for(i=1;i<=NF;i++)$i=toupper(substr($i,1,1)) substr($i,2)}1')"
  sed -i '' "s/CFBundleDisplayName: My App\$/CFBundleDisplayName: $APP_NAME/" project.yml
  NAME="$(sed -n 's/.*CFBundleDisplayName: *//p' project.yml | head -1 | tr -d '"')"
  # Icon: a committed AppIcon wins; otherwise icon.json (symbol + colors) or a letter on a gradient.
  if [ -z "$(find . -name AppIcon.appiconset -not -path './build/*' | head -1)" ]; then
    ICON=App/Assets.xcassets/AppIcon.appiconset
    mkdir -p "$ICON" build
    cat > build/icon.swift <<'SWIFT'
import AppKit

// usage: icon.swift OUT NAME [icon.json]
let args = CommandLine.arguments
let out = args[1], name = args[2]
var cfg: [String: Any] = [:]
if args.count > 3, let d = try? Data(contentsOf: URL(fileURLWithPath: args[3])),
   let j = try? JSONSerialization.jsonObject(with: d) as? [String: Any] { cfg = j }

func color(_ hex: String) -> NSColor? {
    var s = hex.trimmingCharacters(in: CharacterSet(charactersIn: "#"))
    guard s.count == 6, let v = UInt32(s, radix: 16) else { return nil }
    s = ""
    return NSColor(srgbRed: CGFloat((v >> 16) & 255) / 255, green: CGFloat((v >> 8) & 255) / 255, blue: CGFloat(v & 255) / 255, alpha: 1)
}
// Default colors come from the name so every app looks different.
var h: UInt32 = 5381
for u in name.unicodeScalars { h = h &* 33 &+ u.value }
let hue = CGFloat(h % 360) / 360
let colors = ((cfg["colors"] as? [String]) ?? []).compactMap(color)
let top = colors.first ?? NSColor(hue: hue, saturation: 0.55, brightness: 1.0, alpha: 1)
let bottom = colors.count > 1 ? colors[1] : NSColor(hue: fmod(hue + 0.08, 1), saturation: 0.9, brightness: 0.75, alpha: 1)

let size = 1024
let cs = CGColorSpace(name: CGColorSpace.sRGB)!
let ctx = CGContext(data: nil, width: size, height: size, bitsPerComponent: 8, bytesPerRow: 0, space: cs,
                    bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue)!
NSGraphicsContext.current = NSGraphicsContext(cgContext: ctx, flipped: false)
let rect = NSRect(x: 0, y: 0, width: size, height: size)
NSGradient(starting: top, ending: bottom)!.draw(in: rect, angle: -60)

if let sym = cfg["symbol"] as? String,
   let base = NSImage(systemSymbolName: sym, accessibilityDescription: nil),
   let img = base.withSymbolConfiguration(NSImage.SymbolConfiguration(pointSize: 520, weight: .semibold)
        .applying(NSImage.SymbolConfiguration(paletteColors: [.white]))) {
    let s = img.size
    let k = min(560 / s.width, 560 / s.height)
    let w = s.width * k, hh = s.height * k
    let r = NSRect(x: (CGFloat(size) - w) / 2, y: (CGFloat(size) - hh) / 2, width: w, height: hh)
    NSShadow().set()
    img.draw(in: r)
} else {
    let letter = String(name.trimmingCharacters(in: .whitespaces).first ?? "A").uppercased()
    var font = NSFont.systemFont(ofSize: 620, weight: .bold)
    if let d = font.fontDescriptor.withDesign(.rounded) { font = NSFont(descriptor: d, size: 620) ?? font }
    let str = NSAttributedString(string: letter, attributes: [.font: font, .foregroundColor: NSColor.white])
    let t = str.size()
    str.draw(at: NSPoint(x: (CGFloat(size) - t.width) / 2, y: (CGFloat(size) - t.height) / 2))
}
NSGraphicsContext.current?.flushGraphics()
let rep = NSBitmapImageRep(cgImage: ctx.makeImage()!)
try! rep.representation(using: .png, properties: [:])!.write(to: URL(fileURLWithPath: out))
SWIFT
    swiftc -o build/icongen build/icon.swift
    build/icongen "$ICON/icon.png" "${NAME:-App}" "$( [ -f icon.json ] && echo icon.json )"
    cat > "$ICON/Contents.json" <<'JSON'
{"images":[{"filename":"icon.png","idiom":"universal","platform":"ios","size":"1024x1024"}],"info":{"author":"xcode","version":1}}
JSON
  fi
  command -v xcodegen >/dev/null || brew install xcodegen
  xcodegen generate
fi

PROJECT=$(ls -d *.xcodeproj | head -1)
SCHEME="${PROJECT%.xcodeproj}"
AUTH=(-allowProvisioningUpdates -authenticationKeyPath "$KEY"
      -authenticationKeyID "$ASC_KEY_ID" -authenticationKeyIssuerID "$ASC_ISSUER_ID")

xcodebuild archive -project "$PROJECT" -scheme "$SCHEME" \
  -destination 'generic/platform=iOS' -archivePath build/app.xcarchive TARGETED_DEVICE_FAMILY=1 \
  DEVELOPMENT_TEAM="$TEAM_ID" PRODUCT_BUNDLE_IDENTIFIER="$BUNDLE_ID" \
  CURRENT_PROJECT_VERSION="${GITHUB_RUN_NUMBER:-1}" \
  CODE_SIGNING_ALLOWED=NO CODE_SIGNING_REQUIRED=NO CODE_SIGN_IDENTITY=""
# The archive is unsigned on purpose: signing at archive time makes every fresh runner create a new Apple
# Development certificate, and the account soon hits Apple's certificate limit. Signing happens once, in the
# export below, with the cloud-managed distribution certificate that every build reuses.

if [ "$MODE" = "testflight" ]; then
  METHOD="app-store-connect"; DEST="upload"
else
  METHOD="release-testing"; DEST="export"
fi
cat > build/export.plist <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<plist version="1.0"><dict>
<key>method</key><string>$METHOD</string>
<key>destination</key><string>$DEST</string>
<key>teamID</key><string>$TEAM_ID</string>
<key>signingStyle</key><string>automatic</string>
</dict></plist>
EOF
xcodebuild -exportArchive -archivePath build/app.xcarchive \
  -exportPath build/out -exportOptionsPlist build/export.plist "${AUTH[@]}"

if [ "$MODE" = "testflight" ]; then
  # Capture a simulator screenshot for the App Store listing (best effort).
  (
    set +e
    xcodebuild build -project "$PROJECT" -scheme "$SCHEME" -sdk iphonesimulator \
      -destination 'platform=iOS Simulator,name=iPhone 16 Plus' -derivedDataPath build/sim \
      CODE_SIGNING_ALLOWED=NO PRODUCT_BUNDLE_IDENTIFIER="$BUNDLE_ID" || exit 0
    APP=$(find build/sim -name '*.app' -path '*iphonesimulator*' | head -1)
    SIM=$(xcrun simctl list devices available | grep 'iPhone 16 Plus' | head -1 | grep -oE '[0-9A-F]{8}-[0-9A-F-]{27}')
    [ -n "$SIM" ] && [ -n "$APP" ] || exit 0
    xcrun simctl boot "$SIM" && xcrun simctl install "$SIM" "$APP" && xcrun simctl launch "$SIM" "$BUNDLE_ID"
    sleep 8
    xcrun simctl io "$SIM" screenshot build/shot1.png
    curl -fsS -X POST -H "X-Upload-Token: $UPLOAD_TOKEN" -H "Content-Type: image/png" \
      --data-binary @build/shot1.png "${UPLOAD_URL%/ipa}/screenshot"
  ) || true
fi

if [ "$MODE" != "testflight" ]; then
  IPA=$(ls build/out/*.ipa | head -1)
  curl -fsS -X POST -H "X-Upload-Token: $UPLOAD_TOKEN" \
    -H "Content-Type: application/octet-stream" --data-binary @"$IPA" "$UPLOAD_URL"
fi
